import sys
FLAGS = [
    (0x1, 'PAIRED'),
    (0x2, 'PROPER_PAIR'),
    (0x4, 'UNMAP'),
    (0x8, 'MUNMAP'),
    (0x10, 'REVERSE'),
    (0x20, 'MREVERSE'),
    (0x40, 'READ1'),
    (0x80, 'READ2'),
    (0x100, 'SECONDARY'),
    (0x200, 'QCFAIL'),
    (0x400, 'DUP'),
    (0x800, 'SUPPLEMENTARY'),
]
def print_flags(arg):
    if arg.isdigit() or arg.startswith('0x'):
        val = int(arg, 0)
    else:
        val = 0
        names = arg.split(',')
        for name in names:
            for v, n in FLAGS:
                if n == name:
                    val |= v

    names_out = []
    for v, n in FLAGS:
        if val & v:
            names_out.append(n)
    print(f"{hex(val)}\t{val}\t{','.join(names_out)}")

for a in sys.argv[1:]:
    print_flags(a)
